      "path": "lib/approved-plan.js",
      "content": "/** Native plan-review handoff. Approval belongs to one live review, never to model prose. */\nimport { createHash, randomUUID } from 'node:crypto';\nimport { MAX_APPROVED_PLAN_CHARS } from './client-contract.js';\nimport { executeMigration, findSession, foldedHistory, listPresets, resolvePresetTarget } from './migrate.js';\nconst APPROVAL_TTL_MS = 30 * 60_000;\nconst MAX_APPROVALS = 64;\nconst MAX_PAYLOAD_CHARS = 1_024_000;\nconst object = (value) => value !== null && typeof value === 'object' ? value : undefined;\nconst nativeKey = (sourceId, callId) => JSON.stringify([sourceId, callId]);\nfunction decodePayload(encoded) {\n    if (encoded.length > MAX_PAYLOAD_CHARS || !/^[A-Za-z0-9+/_-]+={0,2}$/u.test(encoded)) {\n        throw new Error('Invalid approved-plan payload.');\n    }\n    const bytes = Buffer.from(encoded, 'base64url');\n    const text = bytes.toString('utf8');\n    if (!Buffer.from(text, 'utf8').equals(bytes))\n        throw new Error('Invalid approved-plan UTF-8.');\n    const value = object(JSON.parse(text));\n    if (!value || Object.keys(value).some(key => key !== 'callId' && key !== 'plan')\n        || typeof value.callId !== 'string' || !/^[^\\s]{1,512}$/u.test(value.callId)\n        || typeof value.plan !== 'string' || !value.plan.trim() || value.plan.length > MAX_APPROVED_PLAN_CHARS) {\n        throw new Error('Invalid approved-plan document or review identity.');\n    }\n    return { callId: value.callId, plan: value.plan };\n}\nfunction reviewedPlan(request) {\n    if (request.signal?.aborted || request.questions?.length !== 1)\n        return undefined;\n    const question = object(request.questions[0]);\n    const intent = object(question?.intent);\n    if (intent?.kind !== 'plan-review' || typeof intent.callId !== 'string' || !intent.callId\n        || typeof intent.approve !== 'string' || typeof question?.detail !== 'string'\n        || !question.detail.trim() || question.detail.length > MAX_APPROVED_PLAN_CHARS\n        || question.multiSelect === true || !Array.isArray(question.options)\n        || !question.options.some(option => object(option)?.label === intent.approve))\n        return undefined;\n    return { callId: intent.callId, plan: question.detail };\n}\n/** Observe the public question waterfall without answering ordinary reviews or changing their options. */\nexport function createPlanApprovalBridge(deps) {\n    const reviews = new Map();\n    const approved = new Map();\n    const now = deps.now ?? Date.now;\n    let disposed = false;\n    const prune = () => {\n        for (const [id, record] of approved) {\n            if (!record.inFlight && now() - record.at >= APPROVAL_TTL_MS) {\n                approved.delete(id);\n                reviews.delete(nativeKey(record.sourceId, record.callId));\n            }\n        }\n        for (const [id, record] of approved) {\n            if (approved.size <= MAX_APPROVALS)\n                break;\n            if (!record.inFlight) {\n                approved.delete(id);\n                reviews.delete(nativeKey(record.sourceId, record.callId));\n            }\n        }\n    };\n    const failure = (lang, en, zh) => ({ kind: 'error', text: lang === 'en' ? en : zh });\n    const userState = async (host, sourceId) => {\n        const users = (await foldedHistory(host, sourceId)).filter(message => message.role === 'user').map(message => message.content);\n        return {\n            fingerprint: createHash('sha256').update(JSON.stringify(users)).digest('hex'),\n            context: users.join('\\n\\n').slice(-Math.min(deps.config.sourceCharBudget, 12_000)),\n        };\n    };\n    const run = async (record, host, source, lang) => {\n        try {\n            const state = await userState(host, record.sourceId);\n            if (record.userFingerprint !== undefined && record.userFingerprint !== state.fingerprint) {\n                return failure(lang, 'The source user requests changed. Review a new plan before executing.', '原会话的用户要求已变更，请重新评审计划后执行。');\n            }\n            record.userFingerprint ??= state.fingerprint;\n            record.sourceContext ??= state.context;\n            if (disposed)\n                return failure(lang, 'Bridge was unloaded before execution started.', 'Bridge 已卸载，尚未启动执行。');\n            if (!record.sourceStopped) {\n                if (record.sourceSignal?.aborted)\n                    return failure(lang, 'The original plan review was cancelled. Review the current plan again.', '原计划评审已经取消，请重新评审当前计划。');\n                // Cancellation ends the source's blocking exit_plan_mode call while leaving plan/mode active.\n                // The observer refuses a concurrent native Approve answer once this record is claimed.\n                const cancellation = object(await host.sessions.cancel({ sessionId: record.sourceId }));\n                if (cancellation?.accepted === false || cancellation?.cancelled === false)\n                    throw new Error('The source did not accept cancellation.');\n                record.sourceStopped = true;\n            }\n            if (disposed)\n                return failure(lang, 'Bridge was unloaded before execution started; the plan remains in the source transcript.', 'Bridge 已卸载，尚未启动执行；完整计划仍保留在原会话记录中。');\n            const preset = record.preset;\n            const heading = /^#{1,6}\\s+(.+)$/mu.exec(record.plan)?.[1]?.trim().slice(0, 160)\n                ?? (lang === 'en' ? 'Approved plan' : '已批准计划');\n            const title = `${heading} → ${preset}`;\n            const result = await executeMigration(host, {\n                sessionId: record.sourceId, sourceSession: source, to: preset, summary: record.plan,\n                executionKind: 'approved-plan', sourceContext: record.sourceContext,\n                lang, autoContinue: true, inject: deps.config.inject, goalRounds: deps.config.goalRounds, title,\n            });\n            const lines = lang === 'en' ? [\n                `Created a new session in the ${result.agentPreset} preset for the approved plan.`,\n                `Target session: ${title} · ${result.sessionId}`,\n                result.kickoffSent ? 'The complete approved plan is being executed in the new session; the handoff goal stays paused.'\n                    : 'The target exists but automatic execution could not be confirmed. Open it and inspect the warnings.',\n                'The original planning turn was stopped; the source session remains in plan mode for reference.',\n            ] : [\n                `已在 ${result.agentPreset} 模式下建好新会话，执行已批准的完整计划。`,\n                `目标会话：${title} · ${result.sessionId}`,\n                result.kickoffSent ? '完整计划已逐字交接，新会话开始执行；交接目标保持暂停。'\n                    : '执行会话已创建，但无法确认自动执行已启动；请打开目标并检查警告。',\n                '原规划轮次已停止，原会话仍保留在计划模式，供查阅和继续规划。',\n            ];\n            for (const warning of result.warnings)\n                lines.push(`⚠ ${warning}`);\n            record.result = { kind: 'success', text: lines.join('\\n') };\n            return record.result;\n        }\n        catch (error) {\n            const detail = error instanceof Error ? error.message : String(error);\n            if (!record.sourceStopped && record.live) {\n                record.claimed = false;\n                if (record.approvalId)\n                    approved.delete(record.approvalId);\n                delete record.approvalId;\n                return failure(lang, `Could not stop the planning turn: ${detail}`, `无法停止原规划轮次：${detail}`);\n            }\n            const retry = `/bridge --approved-plan ${record.approvalId ?? ''} --lang ${lang}`;\n            return failure(lang, `Could not create the execution session: ${detail}\\nRetry the approved plan: ${retry}`, `执行会话创建失败：${detail}\\n重试已批准计划：${retry}`);\n        }\n    };\n    return {\n        observe: async (request, next) => {\n            const plan = disposed ? undefined : reviewedPlan(request);\n            const sourceId = request.agent?.session?.id ?? request.agent?.session?.header?.id;\n            if (!plan || !sourceId)\n                return next();\n            const key = nativeKey(sourceId, plan.callId);\n            // A second answerer request must not replace a claim in progress.\n            if (reviews.has(key))\n                return next();\n            const record = { ...plan, sourceId, live: true, claimed: false, sourceStopped: false, at: now(),\n                ...(request.signal ? { sourceSignal: request.signal } : {}),\n            };\n            reviews.set(key, record);\n            try {\n                const answer = await next();\n                if (record.claimed)\n                    throw new Error('Bridge owns this plan approval; execution belongs to a new session.');\n                return answer;\n            }\n            finally {\n                record.live = false;\n                if (!record.claimed && reviews.get(key) === record)\n                    reviews.delete(key);\n            }\n        },\n        execute: async (input) => {\n            const lang = input.lang;\n            if (disposed)\n                return failure(lang, 'Bridge plan approval is unavailable after unload.', 'Bridge 已卸载，无法接收计划批准。');\n            prune();\n            let record;\n            try {\n                if (input.approvePlan64 !== undefined) {\n                    const plan = decodePayload(input.approvePlan64);\n                    record = reviews.get(nativeKey(input.sessionId, plan.callId));\n                    if (!record || record.plan !== plan.plan || (!record.live && !record.claimed)) {\n                        return failure(lang, 'This exact plan is no longer awaiting approval. Reopen a current plan review.', '这份计划已不在等待批准，或内容已变更；请重新打开当前计划评审。');\n                    }\n                }\n                else if (input.approvedPlanId !== undefined) {\n                    record = approved.get(input.approvedPlanId);\n                    if (!record || record.sourceId !== input.sessionId)\n                        return failure(lang, 'No approved plan is bound to this session; review it again.', '当前会话没有这份有效的批准记录，请重新评审计划。');\n                }\n                if (!record)\n                    return failure(lang, 'No plan approval was supplied.', '没有收到计划批准。');\n                if (record.result)\n                    return record.result;\n                if (record.inFlight)\n                    return record.inFlight;\n                const host = deps.hostFor(input.signal);\n                const source = await findSession(host, input.sessionId);\n                if (!source)\n                    return failure(lang, 'The source session is unavailable.', '读不到原计划会话。');\n                const presets = await listPresets(host);\n                const requested = input.preset ?? record.preset ?? source.agentPreset;\n                if (!requested)\n                    return failure(lang, 'Choose an execution preset.', '请指定新执行会话的模式。');\n                const preset = resolvePresetTarget(requested, presets);\n                if (!presets.some(p => p.id === preset))\n                    return failure(lang, `No usable execution preset named ${preset}.`, `没有可用的执行模式 ${preset}。`);\n                // An asynchronous source/preset lookup can race another approval or the native decision.\n                if (record.result)\n                    return record.result;\n                if (record.inFlight)\n                    return record.inFlight;\n                if (!record.live && !record.claimed)\n                    return failure(lang, 'The plan review already settled.', '这份计划评审已经结束。');\n                record.preset = preset;\n                record.claimed = true;\n                record.approvalId ??= randomUUID();\n                record.at = now();\n                approved.set(record.approvalId, record);\n                const selected = record;\n                const operation = run(selected, host, source, lang);\n                selected.inFlight = operation;\n                prune();\n                try {\n                    return await operation;\n                }\n                finally {\n                    delete selected.inFlight;\n                }\n            }\n            catch (error) {\n                return failure(lang, `Invalid plan approval: ${error instanceof Error ? error.message : String(error)}`, `计划批准无效：${error instanceof Error ? error.message : String(error)}`);\n            }\n        },\n        dispose: () => { disposed = true; reviews.clear(); approved.clear(); },\n    };\n}\n"
    },
    {
      "path": "lib/dsh-alpha-host.js",
      "content": "/**\n * DSH v0.1.2/v0.1.3 typed-controller adapter.\n *\n * The alpha removed the legacy ApiProxy service.  Keep that product change at\n * this boundary: migration code continues to consume BridgeHost, while this\n * adapter talks to the Host controllers structurally while the browser half\n * builds against the current client SDK.\n */\nimport { randomUUID } from 'node:crypto';\nimport { createApiProxyHost, probeApiProxy } from './api-rpc.js';\nimport { REQUIRED_BRIDGE_CAPABILITIES, } from './host.js';\nimport { RpcError } from './rpc.js';\nimport { withDshCurrentCwd } from './dsh-session-row.js';\n/** 有快照就继续用快照，避免改变 0.2.1 宿主的分页；否则改走宿主自己的历史页。 */\nfunction historyReader(controller) {\n    if (typeof controller?.inspect === 'function')\n        return controller.inspect;\n    if (typeof controller?.events === 'function')\n        return controller.events;\n    if (typeof controller?.page === 'function')\n        return controller.page;\n    return undefined;\n}\nconst ALPHA_METHODS = {\n    'session.list': services => services.sessionController?.list,\n    'session.create': services => services.sessionController?.create,\n    'session.history': services => historyReader(services.sessionController),\n    'session.models': services => services.sessionController?.modelCatalog,\n    'session.selectModel': services => services.sessionController?.selectModel,\n    'session.prompt': services => services.sessionController?.prompt,\n    'session.cancel': services => services.sessionController?.cancel,\n    'session.rename': services => services.sessionController?.rename,\n    'workspace.list': services => services.workspaceRegistry?.list,\n    'workspace.archiveSession': services => services.workspaceController?.archiveSession,\n    'agentPreset.list': services => services.agentPresets?.remoteExportList,\n    'goal.create': services => services.goals?.remoteExportCreate,\n    'goal.pause': services => services.goals?.pause,\n};\nfunction service(ctx, name) {\n    try {\n        const getter = ctx.get;\n        if (typeof getter === 'function') {\n            const found = getter.call(ctx, name);\n            if (found !== undefined)\n                return found;\n        }\n    }\n    catch {\n        // Cordis returns undefined for an unavailable optional service; custom\n        // Context implementations may throw instead, so fall through to fixtures.\n    }\n    try {\n        return ctx[name];\n    }\n    catch {\n        return undefined;\n    }\n}\nfunction servicesOf(ctx) {\n    return {\n        apiProxy: service(ctx, 'apiProxy'),\n        sessionController: service(ctx, 'sessionController'),\n        workspaceRegistry: service(ctx, 'workspaceRegistry'),\n        workspaceController: service(ctx, 'workspaceController'),\n        agentPresets: service(ctx, 'agentPresets'),\n        goals: service(ctx, 'goals'),\n    };\n}\nfunction failureOf(error) {\n    const value = error;\n    return value?.failure ?? value?.rpc ?? {\n        code: value?.code,\n        message: value?.message,\n        details: value?.details,\n    };\n}\nasync function invoke(method, operation) {\n    try {\n        return await operation();\n    }\n    catch (error) {\n        if (error instanceof RpcError)\n            throw error;\n        const failure = failureOf(error);\n        throw new RpcError(method, failure.code ?? 'internal', failure.message ?? (error instanceof Error ? error.message : String(error)), failure.details);\n    }\n}\nfunction required(method, value) {\n    if (value === undefined)\n        throw new RpcError(method, 'unavailable', `DSH alpha host 没有提供 ${method}`);\n    return value;\n}\nfunction projectionValues(row) {\n    const values = row?.projections?.values;\n    return values !== null && typeof values === 'object' ? values : {};\n}\nfunction sessionRow(row) {\n    const source = row;\n    const values = projectionValues(row);\n    const preset = typeof values.agentPreset === 'string'\n        ? values.agentPreset\n        : typeof source.agentPreset === 'string' ? source.agentPreset : undefined;\n    return withDshCurrentCwd({\n        sessionId: String(source.sessionId ?? ''),\n        ...(typeof source.running === 'boolean' ? { running: source.running } : {}),\n        ...(typeof source.blank === 'boolean' ? { blank: source.blank } : {}),\n        ...(typeof source.cwd === 'string' ? { cwd: source.cwd } : {}),\n        ...(preset === undefined ? {} : { agentPreset: preset }),\n        ...(typeof source.parentSessionId === 'string' ? { parentSessionId: source.parentSessionId } : {}),\n        ...Object.keys(values).length === 0 ? {} : { projections: { values } },\n    });\n}\nfunction currentModel(row) {\n    const selection = projectionValues(row).modelSelection;\n    if (selection === null || typeof selection !== 'object')\n        return undefined;\n    const record = selection;\n    const candidate = record.next ?? record.lastUsed;\n    if (candidate === null || typeof candidate !== 'object')\n        return undefined;\n    const model = candidate;\n    if (typeof model.provider !== 'string' || typeof model.model !== 'string')\n        return undefined;\n    return {\n        provider: model.provider,\n        model: model.model,\n        ...(typeof model.reasoningEffort === 'string' ? { reasoningEffort: model.reasoningEffort } : {}),\n    };\n}\nfunction paginateHistory(events, beforeSeq, maxMessages) {\n    // Snapshot events are ordered. Locate the cursor without copying/scanning\n    // the entire prefix on every page; only allocate the returned window.\n    let end = events.length;\n    if (beforeSeq !== undefined) {\n        let low = 0;\n        while (low < end) {\n            const middle = Math.floor((low + end) / 2);\n            if ((events[middle]?.seq ?? -1) < beforeSeq)\n                low = middle + 1;\n            else\n                end = middle;\n        }\n    }\n    let count = 0;\n    let cut = 0;\n    for (let index = end - 1; index >= 0; index -= 1) {\n        const type = events[index]?.type;\n        if (type !== 'user/message' && type !== 'assistant/message')\n            continue;\n        count += 1;\n        if (count >= maxMessages) {\n            cut = index;\n            break;\n        }\n    }\n    return {\n        events: events.slice(cut, end).map(event => ({ event })),\n        hasMore: cut > 0,\n    };\n}\n/** 把 0.2.2 的 `events`/`page` 结果收成 Bridge 的 `{ events, hasMore }`。 */\nasync function readEventPage(controller, sessionId, beforeSeq, maxMessages, signal) {\n    const read = typeof controller.events === 'function' ? controller.events : controller.page;\n    const page = required('session.history', read);\n    const value = await invoke('session.history', () => page.call(controller, {\n        address: { kind: 'session', sessionId },\n        ...(beforeSeq === undefined ? {} : { beforeSeq }),\n        maxMessages,\n    }, signal));\n    const records = Array.isArray(value?.records) ? value.records : [];\n    return {\n        events: records.flatMap(record => {\n            const event = record?.event;\n            return event !== null && typeof event === 'object' ? [{ event }] : [];\n        }),\n        hasMore: value?.hasMore === true,\n    };\n}\nasync function readSessionHistory(controller, sessionId, beforeSeq, maxMessages, signal) {\n    if (typeof controller?.inspect === 'function') {\n        const inspect = controller.inspect;\n        const value = await invoke('session.history', () => inspect.call(controller, sessionId, signal));\n        return paginateHistory(value.events, beforeSeq, maxMessages);\n    }\n    return readEventPage(required('session.history', controller), sessionId, beforeSeq, maxMessages, signal);\n}\nasync function resolvedAgent(services, sessionId) {\n    const resolve = required('session.resolveAgent', services.sessionController?.resolveAgent);\n    const result = await invoke('session.resolveAgent', () => resolve.call(services.sessionController, sessionId));\n    if (result.error !== undefined) {\n        throw new RpcError('session.resolveAgent', result.error.code ?? 'internal', result.error.message ?? 'DSH alpha 无法恢复目标会话', result.error.details);\n    }\n    return required('session.resolveAgent', result.agent);\n}\n/** Probe the real alpha services instead of the adapter's always-present closures. */\nexport function probeDshAlphaHost(input) {\n    const services = servicesOf(input);\n    return REQUIRED_BRIDGE_CAPABILITIES.map(method => ({\n        method,\n        available: typeof ALPHA_METHODS[method]?.(services) === 'function',\n    }));\n}\n/** Create the semantic BridgeHost over DSH typed Host controllers. */\nexport function createDshAlphaHost(input, signal) {\n    const services = servicesOf(input);\n    const controller = services.sessionController;\n    const abort = signal ?? new AbortController().signal;\n    const host = {\n        descriptor: Object.freeze({ id: 'dsh-typed-controllers', transport: 'in-process' }),\n        sessions: Object.freeze({\n            list: async (request = {}) => {\n                const list = required('session.list', controller?.list);\n                const value = await invoke('session.list', () => list.call(controller, request, abort));\n                return { items: (value.items ?? []).map(sessionRow) };\n            },\n            create: async (request) => {\n                const create = required('session.create', controller?.create);\n                return await invoke('session.create', () => create.call(controller, request));\n            },\n            history: async (request, options) => {\n                const readingSignal = options?.signal && options.signal !== abort ? AbortSignal.any([abort, options.signal]) : abort;\n                return readSessionHistory(controller, request.sessionId, request.beforeSeq, request.maxMessages ?? 60, readingSignal);\n            },\n            historyWindow: async (request) => readSessionHistory(controller, request.sessionId, undefined, request.maxMessages, abort),\n            models: async ({ sessionId }) => {\n                const list = required('session.list', controller?.list);\n                const catalog = required('session.models', controller?.modelCatalog);\n                const [listed, available] = await Promise.all([\n                    invoke('session.list', () => list.call(controller, {}, abort)),\n                    invoke('session.models', () => catalog.call(controller)),\n                ]);\n                const row = (listed.items ?? []).find(item => item.sessionId === sessionId);\n                return {\n                    ...available,\n                    current: currentModel(row) ?? available.default,\n                };\n            },\n            selectModel: request => {\n                const select = required('session.selectModel', controller?.selectModel);\n                return invoke('session.selectModel', () => select.call(controller, { ...request }));\n            },\n            prompt: request => {\n                const prompt = required('session.prompt', controller?.prompt);\n                return invoke('session.prompt', () => prompt.call(controller, {\n                    ...request,\n                    requestId: `bridge-${randomUUID()}`,\n                }, abort));\n            },\n            cancel: request => {\n                const cancel = required('session.cancel', controller?.cancel);\n                return invoke('session.cancel', () => cancel.call(controller, request));\n            },\n            rename: request => {\n                const rename = required('session.rename', controller?.rename);\n                return invoke('session.rename', () => rename.call(controller, request));\n            },\n            attachment: request => {\n                const attachment = required('session.attachment', controller?.attachment);\n                return invoke('session.attachment', () => attachment.call(controller, request));\n            },\n        }),\n        workspaces: Object.freeze({\n            list: async () => {\n                const list = required('workspace.list', services.workspaceRegistry?.list);\n                const rows = await invoke('workspace.list', () => list.call(services.workspaceRegistry));\n                return {\n                    items: rows.map((item) => {\n                        const row = item;\n                        return {\n                            workspaceId: String(row.id ?? row.workspaceId ?? ''),\n                            sessionIds: Array.isArray(row.sessionIds) ? row.sessionIds.map(String) : [],\n                        };\n                    }),\n                };\n            },\n            archiveSession: request => {\n                const archive = required('workspace.archiveSession', services.workspaceController?.archiveSession);\n                return invoke('workspace.archiveSession', () => archive.call(services.workspaceController, request));\n            },\n        }),\n        presets: Object.freeze({\n            list: async () => {\n                const list = required('agentPreset.list', services.agentPresets?.remoteExportList);\n                return await invoke('agentPreset.list', () => list.call(services.agentPresets));\n            },\n        }),\n        goals: Object.freeze({\n            create: async (request) => {\n                const agent = await resolvedAgent(services, request.sessionId);\n                const create = required('goal.create', services.goals?.remoteExportCreate);\n                return await invoke('goal.create', () => create.call(services.goals, agent, {\n                    objective: request.objective,\n                    maxGoalRounds: request.maxGoalRounds,\n                }));\n            },\n            pause: async (request) => {\n                const agent = await resolvedAgent(services, request.sessionId);\n                const pause = required('goal.pause', services.goals?.pause);\n                return await invoke('goal.pause', () => pause.call(services.goals, agent, request.ref));\n            },\n            clear: async (request) => {\n                const agent = await resolvedAgent(services, request.sessionId);\n                const clear = required('goal.clear', services.goals?.clear);\n                return await invoke('goal.clear', () => clear.call(services.goals, agent, request.ref));\n            },\n        }),\n    };\n    return Object.freeze(host);\n}\n/** Prefer the stable rc.2 path when present; otherwise use alpha controllers. */\nexport function resolveDshHost(input, signal) {\n    const services = servicesOf(input);\n    if (services.apiProxy !== undefined)\n        return createApiProxyHost(services.apiProxy, signal);\n    if (services.sessionController !== undefined)\n        return createDshAlphaHost(services, signal);\n    throw new RpcError('bridge.host', 'unavailable', '当前 DSH 没有可用的 apiProxy 或 typed sessionController');\n}\n/** Probe the active generation using its native surface. */\nexport function probeDshHost(input) {\n    const services = servicesOf(input);\n    if (services.apiProxy !== undefined)\n        return probeApiProxy(services.apiProxy);\n    return probeDshAlphaHost(services);\n}\n"
