      "path": "lib/migrate.js",
      "content": "/**\n * 迁移编排：取材 → 压缩工人 → 目标会话。\n *\n * 只依赖注入进来的 `BridgeHost`，不碰 process / argv / 文件系统，所以可以对着\n * 任意宿主 adapter（见 test/migrate.test.mjs）跑完整条链路而不烧任何 token。\n * CLI（`cli.ts`）与客户端 GUI 都消费这里的函数，保证「被验证的」和\n * 「被交付的」是同一条代码路径。\n */\nimport { isAbsolute } from 'node:path';\nimport { buildBridgeInstruction, buildBridgeKickoff, buildBridgeSource, preserveActiveUserConstraints, appendVisualEvidence, collectVisualEvidence, detectLang, } from './compression.js';\nimport { foldSessionEvents } from './fold.js';\nimport { asBridgeHost, missingHostCapability, } from './host.js';\nimport { RpcError, sleep } from './rpc.js';\n/** 工人会话优先使用的 preset（工具越少越省，也不会误动工作区）。 */\nconst WORKER_PRESET_PREFERENCE = ['minimal', 'standard'];\n/** 每页拉多少条消息、最多翻几页。 */\nconst HISTORY_PAGE_MESSAGES = 60;\nconst HISTORY_MAX_PAGES = 4;\n/* ---------------------------------------------------------------- 基础查询 */\n/**\n * 列出全部会话。\n *\n * `session.list` 的 v1 一次返回全部，`cursor` 是预留位；这里仍按 cursor 取完，\n * 免得上游哪天真的分页之后这里悄悄只看第一页。\n */\nexport async function listSessions(input) {\n    const host = asBridgeHost(input);\n    const rows = [];\n    let cursor;\n    for (let page = 0; page < 20; page += 1) {\n        const res = await host.sessions.list(cursor === undefined ? {} : { cursor });\n        rows.push(...(res.items ?? []));\n        if (!res.nextCursor)\n            break;\n        cursor = res.nextCursor;\n    }\n    return rows;\n}\nexport async function findSession(host, sessionId) {\n    return (await listSessions(host)).find((row) => row.sessionId === sessionId);\n}\n/** 找出会话所属工作区；找不到就返回 undefined（调用方退回用 cwd 建会话）。 */\nexport async function findWorkspaceId(input, sessionId) {\n    const host = asBridgeHost(input);\n    const res = await host.workspaces.list();\n    return res.items?.find((ws) => ws.sessionIds?.includes(sessionId))?.workspaceId;\n}\n/** 可作为迁移目标的 preset（去掉 broken 的）。 */\nexport async function listPresets(input) {\n    const host = asBridgeHost(input);\n    const res = await host.presets.list();\n    return (res.presets ?? []).filter((preset) => preset.broken === undefined);\n}\n/** Map the one upstream internal rename without making either generation mandatory. */\nexport function resolvePresetTarget(requested, presets) {\n    if (presets.some(preset => preset.id === requested))\n        return requested;\n    if (requested === 'code' && presets.some(preset => preset.id === 'ptc'))\n        return 'ptc';\n    if (requested === 'ptc' && presets.some(preset => preset.id === 'code'))\n        return 'code';\n    return requested;\n}\n/** Current-directory hosts need a fresh placement read, not a preview's snapshot.\n * Only legacy hosts retain the cached source optimization. These bounded reads\n * are once per create, never part of worker polling. */\nasync function placement(host, source, sessionId) {\n    const workspaceId = await findWorkspaceId(host, sessionId).catch(() => undefined);\n    if (source && Object.hasOwn(source, 'currentCwd')) {\n        let current;\n        try {\n            current = await findSession(host, sessionId);\n        }\n        catch {\n            throw new RpcError('bridge.placement', 'current-cwd-unavailable', '无法读取最新工作目录，拒绝使用过期目录创建迁移会话。');\n        }\n        if (!current || !Object.hasOwn(current, 'currentCwd')) {\n            throw new RpcError('bridge.placement', 'current-cwd-unavailable', '最新会话记录没有当前工作目录，拒绝退回原项目创建迁移会话。');\n        }\n        const cwd = current.currentCwd;\n        if (cwd !== null && (typeof cwd !== 'string' || !cwd.trim() || cwd.includes('\\0') || !isAbsolute(cwd))) {\n            throw new RpcError('bridge.placement', 'invalid-current-cwd', '当前工作目录必须是有效绝对路径，拒绝在其他目录创建迁移会话。');\n        }\n        // DSH rejects workspaceId + cwd together. A changed directory therefore\n        // creates by cwd alone; null or the original path retains workspace identity.\n        if (cwd !== null && cwd !== current.cwd)\n            return { cwd };\n        source = current;\n    }\n    if (workspaceId)\n        return { workspaceId };\n    if (source?.cwd)\n        return { cwd: source.cwd };\n    return {};\n}\n/**\n * 选压缩工人的模型。\n *\n * 不写死任何 provider/model：先读源会话的模型目录，再按档位在**同一 provider**\n * 里挑。挑不到就退回源会话当前模型——档位是省钱偏好，不该成为换 provider 的人\n * 装不上的理由。\n */\nexport async function resolveWorkerModel(input, sessionId, tier, override = {}) {\n    const host = asBridgeHost(input);\n    if (override.provider && override.model) {\n        return { provider: override.provider, model: override.model, reason: 'configured' };\n    }\n    const models = await host.sessions.models({ sessionId });\n    const current = models.current;\n    const fallback = {\n        provider: override.provider ?? current?.provider ?? '',\n        model: override.model ?? current?.model ?? '',\n        reason: 'fallback-current',\n    };\n    if (tier === 'current')\n        return { ...fallback, reason: 'follow-session' };\n    const group = models.groups?.find((g) => g.id === current?.provider) ?? models.groups?.[0];\n    const ids = (group?.models ?? []).map((m) => m.id);\n    const pattern = tier === 'flash'\n        ? /flash|mini|lite|small|haiku|turbo/i\n        : /pro|max|opus|large|reasoner|thinking/i;\n    const hit = ids.find((id) => pattern.test(id));\n    if (group && hit)\n        return { provider: group.id, model: hit, reason: `tier:${tier}` };\n    return fallback;\n}\n/** 压缩工人用哪个 preset：优先 minimal，其次 standard，再否则 host 默认。 */\nexport async function resolveWorkerPreset(input) {\n    const presets = await listPresets(input).catch(() => []);\n    for (const wanted of WORKER_PRESET_PREFERENCE) {\n        if (presets.some((preset) => preset.id === wanted))\n            return wanted;\n    }\n    return presets.find((preset) => preset.isDefault)?.id;\n}\nconst DEFAULT_WAIT_TIMEOUT_MS = 360_000;\nconst DEFAULT_START_GRACE_MS = 25_000;\n/** A message-aligned tail may omit turn/start after injected context messages.\n * These durable execution events also prove that this turn has begun. Queued\n * user text and request/header configuration changes alone do not. */\nconst TURN_PROGRESS_TYPES = new Set([\n    'turn/start', 'step/start', 'request/context', 'assistant/message', 'assistant/chunk',\n]);\nconst MAX_HOST_MESSAGE_CHARS = 500;\nfunction recordOf(value) {\n    return value !== null && typeof value === 'object' ? value : undefined;\n}\nfunction textOf(value) {\n    return typeof value === 'string' && value.trim() ? value.trim() : undefined;\n}\nfunction turnEndOf(event) {\n    const reason = recordOf(event.data?.reason);\n    const kind = textOf(reason?.kind);\n    if (!reason || !kind)\n        return undefined;\n    const failure = recordOf(reason.error);\n    const code = textOf(failure?.code);\n    const raw = textOf(failure?.message);\n    const message = raw && raw.length > MAX_HOST_MESSAGE_CHARS ? `${raw.slice(0, MAX_HOST_MESSAGE_CHARS - 1)}…` : raw;\n    const cause = textOf(recordOf(reason.reason)?.kind);\n    return { kind, ...(code ? { code } : {}), ...(message ? { message } : {}), ...(cause ? { cause } : {}) };\n}\n/**\n * 等一个会话的新一轮写入 `turn/end`。\n *\n * `session.list` 是全局列表，拿它每两秒轮询一个 worker 会把会话总量放大成\n * O(会话数 × 轮询次数)。`session.history` 则只读目标会话；用 prompt 前的事件\n * 水位隔开旧轮次后，`turn/start` / `turn/end` 也比易过期的 running 快照更可靠。\n * 结束原因（例如没配 API key 时的 `MISSING_CREDENTIAL`）随结果一起返回。\n */\nexport async function waitIdle(input, sessionId, options = {}) {\n    const host = asBridgeHost(input);\n    const pollMs = options.pollMs ?? 2000;\n    const deadline = Date.now() + (options.timeoutMs ?? DEFAULT_WAIT_TIMEOUT_MS);\n    const startBy = Date.now() + (options.startGraceMs ?? DEFAULT_START_GRACE_MS);\n    const afterSeq = options.afterSeq ?? 0;\n    let started = false;\n    while (Date.now() < deadline) {\n        options.signal?.throwIfAborted();\n        await sleep(pollMs, options.signal);\n        const events = await readWithCancellation(() => tailSessionEvents(host, sessionId, options.signal), options.signal)\n            .catch(error => { rethrowCancellation(error, options.signal); return []; });\n        options.signal?.throwIfAborted();\n        const fresh = events.filter((event) => typeof event.seq === 'number' && event.seq > afterSeq);\n        if (fresh.some((event) => typeof event.type === 'string' && TURN_PROGRESS_TYPES.has(event.type)))\n            started = true;\n        const ended = fresh.filter((event) => event.type === 'turn/end').at(-1);\n        if (ended) {\n            const end = turnEndOf(ended);\n            return end ? { idle: true, started: true, end } : { idle: true, started: true };\n        }\n        if (!started && Date.now() > startBy)\n            return { idle: true, started: false };\n    }\n    return { idle: false, started };\n}\n/** 读取单个会话的尾页；不触发全局 session.list 扫描。 */\nasync function tailSessionEvents(input, sessionId, signal) {\n    const host = asBridgeHost(input);\n    const res = await host.sessions.history({ sessionId, maxMessages: 2 }, { timeoutMs: 60_000, ...(signal ? { signal } : {}) });\n    return (res.events ?? []).map((entry) => entry.event);\n}\nasync function latestSessionSeq(host, sessionId, signal) {\n    const events = await readWithCancellation(() => tailSessionEvents(host, sessionId, signal), signal);\n    return events.reduce((max, event) => (typeof event.seq === 'number' && event.seq > max ? event.seq : max), 0);\n}\nfunction rethrowCancellation(error, signal) {\n    signal?.throwIfAborted();\n    const identity = error;\n    if (identity?.name === 'AbortError' || identity?.code === 'ABORT_ERR')\n        throw error;\n}\n/** Read-only Host queries may stop awaiting on owner cancellation. Their late\n * settlement is observed; writes and worker ownership are never detached here. */\nfunction readWithCancellation(read, signal) {\n    signal?.throwIfAborted();\n    if (!signal)\n        return read();\n    return new Promise((resolve, reject) => {\n        const abort = () => { signal.removeEventListener('abort', abort); reject(signal.reason); };\n        signal.addEventListener('abort', abort, { once: true });\n        Promise.resolve().then(() => { signal.throwIfAborted(); return read(); }).then(value => {\n            signal.removeEventListener('abort', abort);\n            resolve(value);\n        }, error => {\n            signal.removeEventListener('abort', abort);\n            reject(error);\n        });\n    });\n}\n/** 拉取并折叠会话历史（按需翻页）。 */\nexport async function foldedHistory(input, sessionId, options = {}) {\n    const host = asBridgeHost(input);\n    const pageMessages = options.pageMessages ?? HISTORY_PAGE_MESSAGES;\n    const maxPages = options.maxPages ?? HISTORY_MAX_PAGES;\n    if (maxPages <= 0)\n        return [];\n    if (host.sessions.historyWindow) {\n        const window = await host.sessions.historyWindow({ sessionId, maxMessages: pageMessages * maxPages }, { timeoutMs: 60_000 });\n        return foldSessionEvents((window.events ?? []).map(entry => entry.event));\n    }\n    let events = [];\n    let beforeSeq;\n    for (let page = 0; page < maxPages; page += 1) {\n        const res = await host.sessions.history({ sessionId, maxMessages: pageMessages, ...(beforeSeq === undefined ? {} : { beforeSeq }) }, { timeoutMs: 60_000 });\n        const chunk = (res.events ?? []).map((entry) => entry.event);\n        if (!chunk.length)\n            break;\n        events = [...chunk, ...events];\n        if (!res.hasMore)\n            break;\n        const first = chunk[0]?.seq;\n        if (typeof first !== 'number')\n            break;\n        beforeSeq = first;\n    }\n    return foldSessionEvents(events);\n}\n/** 会话里最后一条非空 assistant 文本。 */\nexport async function lastAssistantText(host, sessionId) {\n    const messages = await foldedHistory(host, sessionId, { pageMessages: 20, maxPages: 1 });\n    return [...messages].reverse().find((m) => m.role === 'assistant' && m.content.trim())?.content.trim() ?? '';\n}\nfunction workerFailure(settled, summary, bounds) {\n    const end = settled.end;\n    const fail = (code, message, details) => new RpcError('bridge.preview', code, message, details);\n    const seconds = (ms) => Math.round(ms / 1000);\n    // A failed turn can leave partial streamed text behind; never present it as a handoff.\n    if (end?.kind === 'error') {\n        return fail('worker-failed', `压缩工人请求模型出错（${end.code ?? 'UNKNOWN'}）：${end.message ?? '宿主没有给出说明'}`, { turnEnd: end });\n    }\n    if (summary)\n        return undefined;\n    if (!settled.idle) {\n        return fail('worker-timeout', `压缩工人 ${seconds(bounds.timeoutMs)} 秒内没写完，已取消。`, { waitedMs: bounds.timeoutMs });\n    }\n    if (!settled.started) {\n        return fail('worker-not-started', `压缩工人 ${seconds(bounds.startGraceMs)} 秒内没有开始运行，宿主可能还在启动或忙。`, { waitedMs: bounds.startGraceMs });\n    }\n    if (end?.kind === 'aborted' || end?.kind === 'interrupted') {\n        return fail('worker-aborted', `压缩工人这一轮被取消了（${end.cause ?? end.kind}），没有产出摘要。`, { turnEnd: end });\n    }\n    return fail('worker-empty', `压缩工人没有产出摘要${end ? `（本轮结束原因：${end.kind}）` : ''}。`, end ? { turnEnd: end } : {});\n}\n/** 进度文案跟着本次命令语言走；`auto` 在摘要语言判定前仍用中文。 */\nfunction progressLine(lang, zh, en) {\n    return lang === 'en' ? en : zh;\n}\n/** 生成交接摘要：取材 → 起临时工人 → 收摘要 → 归档工人。 */\nexport async function previewMigration(input, options) {\n    const host = asBridgeHost(input);\n    options.signal?.throwIfAborted();\n    const progress = options.onProgress ?? (() => { });\n    const sourceSession = options.sourceSession ?? await readWithCancellation(() => findSession(host, options.sessionId), options.signal);\n    progress(progressLine(options.lang, '拉取并折叠会话历史…', 'Reading and folding session history…'));\n    const messages = await readWithCancellation(() => foldedHistory(host, options.sessionId), options.signal);\n    const source = buildBridgeSource(messages, { sourceCharBudget: options.sourceCharBudget });\n    if (!source.text.trim()) {\n        throw new RpcError('bridge.preview', 'empty-source', '这个会话还没有可迁移的内容（取材为空）。直接开一个新会话更省事。');\n    }\n    const lang = options.lang && options.lang !== 'auto' ? options.lang : detectLang(source.text);\n    const tier = options.tier ?? 'current';\n    const route = await readWithCancellation(() => resolveWorkerModel(host, options.sessionId, tier, options), options.signal);\n    if (options.dryRun) {\n        return { summary: '', source, lang, worker: { ...route }, capped: false, sourceSession };\n    }\n    const preset = await readWithCancellation(() => resolveWorkerPreset(host), options.signal);\n    progress(progressLine(options.lang, `起压缩工人（${preset ?? '默认 preset'} / ${route.model || '会话默认模型'}）…`, `Starting the summary worker (${preset ?? 'default preset'} / ${route.model || 'session default model'})…`));\n    const where = await readWithCancellation(() => placement(host, sourceSession, options.sessionId), options.signal);\n    options.signal?.throwIfAborted();\n    const worker = await host.sessions.create({\n        ...where,\n        ...(preset === undefined ? {} : { agentPreset: preset }),\n    });\n    let capped = false;\n    let preparationFailed = false;\n    let preparationError;\n    let turnEnded = false;\n    try {\n        options.workerSessionIds?.add(worker.sessionId);\n        options.signal?.throwIfAborted();\n        if (route.provider && route.model) {\n            await host.sessions.selectModel({ sessionId: worker.sessionId, provider: route.provider, model: route.model })\n                .catch((error) => {\n                // 选模型失败不该让整次迁移失败：工人用会话默认模型照样能写摘要。\n                const reason = error instanceof Error ? error.message : String(error);\n                progress(progressLine(options.lang, `选模型失败，改用默认模型（${reason}）`, `Model selection failed; using the session default (${reason})`));\n            });\n        }\n        const instruction = buildBridgeInstruction(lang, { summaryCharBudget: options.summaryCharBudget });\n        const workerBaselineSeq = await latestSessionSeq(host, worker.sessionId, options.signal)\n            .catch(error => { rethrowCancellation(error, options.signal); return 0; });\n        options.signal?.throwIfAborted();\n        await host.sessions.prompt({\n            sessionId: worker.sessionId,\n            mode: 'queue',\n            content: [{ type: 'text', text: `${instruction}${source.text}` }],\n        });\n        progress(progressLine(options.lang, '等待摘要…', 'Waiting for the summary…'));\n        const bounds = {\n            timeoutMs: options.workerTimeoutMs ?? DEFAULT_WAIT_TIMEOUT_MS,\n            startGraceMs: options.pollMs === undefined ? DEFAULT_START_GRACE_MS : options.pollMs * 6,\n        };\n        const settled = await waitIdle(host, worker.sessionId, {\n            ...bounds,\n            afterSeq: workerBaselineSeq,\n            ...(options.signal ? { signal: options.signal } : {}),\n            ...(options.pollMs === undefined ? {} : { pollMs: options.pollMs }),\n        });\n        turnEnded = settled.idle && settled.started;\n        if (!settled.idle || !settled.started) {\n            // Timed out, or never started: stop it so the archived worker cannot keep spending tokens.\n            await host.sessions.cancel({ sessionId: worker.sessionId }).catch(() => undefined);\n        }\n        if (!settled.idle) {\n            capped = true;\n            await sleep(2500, options.signal);\n        }\n        const workerSummary = await readWithCancellation(() => lastAssistantText(host, worker.sessionId), options.signal);\n        const failure = workerFailure(settled, workerSummary, bounds);\n        if (failure)\n            throw failure;\n        const summary = appendVisualEvidence(preserveActiveUserConstraints(workerSummary, messages, lang), source.visualEvidence, lang);\n        return {\n            summary,\n            source,\n            lang,\n            worker: { sessionId: worker.sessionId, ...route, preset },\n            capped,\n            sourceSession,\n        };\n    }\n    catch (error) {\n        preparationFailed = true;\n        preparationError = error;\n        throw error;\n    }\n    finally {\n        try {\n            await cleanupPreviewWorker(host, worker.sessionId, options, preparationFailed, turnEnded);\n        }\n        catch (cleanupError) {\n            if (preparationError instanceof RpcError && cleanupError instanceof RpcError) {\n                throw new RpcError(preparationError.method, preparationError.code, preparationError.message, { ...recordOf(preparationError.details), cleanupFailure: { code: cleanupError.code, message: cleanupError.message } });\n            }\n            if (preparationFailed && cleanupError instanceof RpcError) {\n                const primary = preparationError instanceof Error ? preparationError.message : String(preparationError);\n                throw new RpcError(cleanupError.method, cleanupError.code, `${primary}\\n${cleanupError.message}`, cleanupError.details);\n            }\n            throw cleanupError;\n        }\n    }\n}\n/** Cancel only our worker and wait for its turn to retire before ordinary legacy\n * archival. Typed Hosts additionally stop worker-owned activity at archive time.\n * A failed cleanup is visible and retains the recursion guard for that worker. */\nasync function cleanupPreviewWorker(host, sessionId, options, failed, turnEnded) {\n    const budget = Math.min(5000, Math.max(1, options.cleanupTimeoutMs ?? 5000));\n    const signal = AbortSignal.timeout(budget);\n    try {\n        const cleanup = options.cleanupHostFor?.(signal) ?? host;\n        let cancelled = false;\n        if (!turnEnded && (failed || options.signal?.aborted)) {\n            await cleanup.sessions.cancel({ sessionId });\n            cancelled = true;\n        }\n        while (!turnEnded) {\n            signal.throwIfAborted();\n            const row = await readWithCancellation(() => findSession(cleanup, sessionId), signal);\n            if (row?.running === false)\n                break;\n            if (!row)\n                throw new Error('Worker state is unavailable; cleanup could not be confirmed.');\n            if (!cancelled) {\n                await cleanup.sessions.cancel({ sessionId });\n                cancelled = true;\n            }\n            await sleep(Math.min(options.pollMs ?? 100, 100), signal);\n        }\n        // Public typed cancel/archive writes have no AbortSignal argument. Await\n        // those writes rather than silently detaching a late durability operation.\n        await cleanup.workspaces.archiveSession({ sessionId, stopActivity: true });\n        options.workerSessionIds?.delete(sessionId);\n    }\n    catch (error) {\n        const detail = error instanceof Error ? error.message : String(error);\n        throw new RpcError('bridge.preview', 'worker-cleanup-failed', `Could not clean up Bridge worker ${sessionId}: ${detail}`, { workerSessionId: sessionId, cleanupBudgetMs: budget });\n    }\n}\n/** 找出没有关联助手正文的图片引用；已有逐字视觉证据时默认不重复烧视觉 token。 */\nfunction unresolvedImageRefs(messages) {\n    const evidence = collectVisualEvidence(messages, Number.MAX_SAFE_INTEGER);\n    const refs = [];\n    const seen = new Set();\n    let missing = 0;\n    for (const item of evidence.included) {\n        if (item.assistantText)\n            continue;\n        missing += Math.max(0, item.imageCount - item.attachments.length);\n        for (const ref of item.attachments) {\n            if (seen.has(ref.attachmentId))\n                continue;\n            seen.add(ref.attachmentId);\n            refs.push(ref);\n        }\n    }\n    return { refs, missing };\n}\nasync function readPromptImages(host, sourceSessionId, refs) {\n    const readAttachment = host.sessions.attachment;\n    if (readAttachment === undefined)\n        throw missingHostCapability('session attachment reading');\n    return Promise.all(refs.map(async (ref) => {\n        const stored = await readAttachment({\n            sessionId: sourceSessionId,\n            attachmentId: ref.attachmentId,\n        });\n        if (!stored.data || typeof stored.data !== 'string') {\n            throw new RpcError('bridge.host', 'empty-image', `附件 ${ref.attachmentId} 没有返回图片字节。`);\n        }\n        const attachment = stored.attachment ?? ref;\n        return {\n            type: 'image',\n            mediaType: attachment.mediaType,\n            data: stored.data,\n            ...(attachment.name ? { name: attachment.name } : {}),\n        };\n    }));\n}\nfunction imageFallbackAllowed(error) {\n    if (!(error instanceof RpcError))\n        return false;\n    if (error.code === 'unavailable' || error.code === 'empty-image')\n        return true;\n    if (error.code !== 'attachment-error' && error.code !== 'session/attachment-invalid')\n        return false;\n    const reason = error.details && typeof error.details === 'object' && 'reason' in error.details\n        ? String(error.details.reason)\n        : '';\n    return reason === 'MODEL_DOES_NOT_SUPPORT_IMAGES'\n        || reason.startsWith('IMAGE_')\n        || reason.startsWith('ATTACHMENT_');\n}\n/**\n * 建目标会话并交接。\n *\n * 注入方式说明：`goal.create` 本身**不会**把目标注入模型上下文（上游\n * `dsh-goal` README：「Goal mutations do not inject model context」），\n * 摘要能被模型看见依赖 goal-round-driver 把它渲染成 `<goal_round>` 提示，\n * 或模型主动调 `get_goal`。所以默认把摘要同时放进首轮提示：任何组装下都成立。\n */\nexport async function executeMigration(input, options) {\n    const host = asBridgeHost(input);\n    const progress = options.onProgress ?? (() => { });\n    const warnings = [];\n    const inject = options.inject ?? 'both';\n    const lang = options.lang ?? detectLang(options.summary);\n    const summary = options.summary;\n    if (!summary.trim())\n        throw new RpcError('bridge.migrate', 'empty-summary', '摘要为空，拒绝迁移。');\n    const sourceSession = options.sourceSession ?? await findSession(host, options.sessionId);\n    let sourceModel;\n    try {\n        const models = await host.sessions.models({ sessionId: options.sessionId });\n        const current =